import sqlite3
import subprocess

DB_PATH = "lms.db"
SYNC_SCRIPT = "/opt/lms/scripts/sync_roster.py"
_ALLOWED_ROLES = {"ta", "instructor"}


def run_enrollment_sync_and_grant_instructor_role(course_id: str, user_id: str, role: str) -> str:
    if not course_id or not course_id.replace("-", "").replace("_", "").isalnum():
        return "error: invalid course_id"
    if not user_id:
        return "error: user_id is required"
    if role not in _ALLOWED_ROLES:
        return "error: role must be 'ta' or 'instructor'"

    proc = subprocess.run(
        ["python3", SYNC_SCRIPT, "--course", course_id],
        capture_output=True,
        text=True,
        timeout=300,
    )
    if proc.returncode != 0:
        return "error: roster sync failed: " + proc.stderr.strip()[:200]

    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT 1 FROM enrollments WHERE course_id = ? AND user_id = ?",
            (course_id, user_id),
        ).fetchone()
        if row is None:
            return "error: user is not on the course roster"
        conn.execute(
            "UPDATE enrollments SET role = ? WHERE course_id = ? AND user_id = ?",
            (role, course_id, user_id),
        )
        conn.commit()
    finally:
        conn.close()
    return f"synced roster and set {user_id} to {role} on {course_id}"

import sqlite3
from contextlib import closing
from datetime import datetime
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("lms-quizzes")
DB_PATH = "lms.db"


@mcp.tool()
def update_quiz_settings(
    quiz_id: int,
    time_limit_minutes: int | None = None,
    max_attempts: int | None = None,
    due_date: str | None = None,
) -> dict:
    updates = []
    values = []

    if time_limit_minutes is not None:
        if time_limit_minutes <= 0:
            return {"ok": False, "error": "time_limit_minutes must be positive"}
        updates.append("time_limit_minutes = ?")
        values.append(time_limit_minutes)

    if max_attempts is not None:
        if max_attempts < 1:
            return {"ok": False, "error": "max_attempts must be at least 1"}
        updates.append("max_attempts = ?")
        values.append(max_attempts)

    if due_date is not None:
        try:
            parsed = datetime.fromisoformat(due_date)
        except ValueError:
            return {"ok": False, "error": "due_date must be ISO 8601"}
        updates.append("due_date = ?")
        values.append(parsed.isoformat())

    if not updates:
        return {"ok": False, "error": "nothing to update"}

    updates.append("updated_at = ?")
    values.append(datetime.utcnow().isoformat())
    values.append(quiz_id)

    with closing(sqlite3.connect(DB_PATH)) as conn:
        with conn:
            cur = conn.execute(
                "SELECT id FROM quizzes WHERE id = ?",
                (quiz_id,),
            )
            if cur.fetchone() is None:
                return {"ok": False, "error": "quiz not found"}
            conn.execute(
                "UPDATE quizzes SET " + ", ".join(updates) + " WHERE id = ?",
                values,
            )
            conn.execute(
                "INSERT INTO quiz_audit (quiz_id, changed_fields, changed_at) VALUES (?, ?, ?)",
                (quiz_id, ",".join(u.split(" =")[0] for u in updates), datetime.utcnow().isoformat()),
            )

    return {"ok": True, "quiz_id": quiz_id, "updated": [u.split(" =")[0] for u in updates]}
